/* This file defines the various widgets used across the application. */

/* Default Button Styles */

.button {
  --icon-size: 16px;
  appearance: none;
  background-color: var(--button-background-color);
  color: var(--button-text-color);
  border: var(--button-border-size) solid var(--button-border-color);
  border-radius: var(--button-border-radius);
  padding: var(--button-padding);
  margin: var(--button-margin);
  min-inline-size: 6em;
  -moz-context-properties: fill, stroke;
  fill: color-mix(in srgb, currentColor 20%, transparent);
  stroke: currentColor;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: inherit;

  @media (prefers-reduced-motion: no-preference) {
    transition:
      background-color 0.15s ease,
      border-color 0.15s ease,
      color 0.15s ease,
      box-shadow 0.15s ease;
  }

  &:enabled {
    &:hover {
      color: var(--button-hover-text-color);
      background-color: var(--button-hover-background-color);
      border-color: var(--button-border-color);

      &:active {
        background-color: var(--button-active-background-color);
        border-color: var(--button-border-color);
      }
    }

    &:focus-visible {
      outline: var(--focus-outline);
      outline-offset: var(--focus-outline-offset);
    }
  }

  &[aria-pressed="true"] {
    box-shadow: var(--button-pressed-shadow);
    background-color: var(--button-active-background-color);
  }

  &:disabled {
    opacity: 0.4;
    pointer-events: none;
  }

  &[hidden] {
    display: none;
  }

  &.icon-button {
    background-image: none;
    background-size: var(--icon-size);
    background-position: var(--button-padding) center;
    background-repeat: no-repeat;
    padding-inline-start: calc(var(--button-padding) * 2 + var(--icon-size));
    padding-inline-end: calc(var(--button-padding) * 2);
    min-inline-size: 0;

    &:dir(rtl),
    &:-moz-locale-dir(rtl) {
      background-position-x: right var(--button-padding);
    }
  }

  &.icon-only {
    background-position: center;
    /* 2px at the end for the border. */
    block-size: calc(var(--button-padding) * 2 + var(--icon-size) + 2px);
    padding: 0;
    aspect-ratio: 1;

    &.button-round {
      --button-border-radius: 50%;
    }
  }

  &.toolbar-button,
  &.unified-toolbar-button {
    background-color: transparent;
    color: currentColor;
    border-color: transparent;
    margin-block: 4px;
  }

  &.toolbar-button[open="true"],
  &.toolbar-button:not([disabled]):hover,
  &.unified-toolbar-button:enabled:is([aria-pressed="true"], :hover) {
